'use client';

import * as React from 'react';

import {Toast} from '@workday/canvas-kit-react/toast';
import {Box} from '@workday/canvas-kit-react/layout';
import {createStyles} from '@workday/canvas-kit-styling';
import {system} from '@workday/canvas-tokens-web';
import {
  checkIcon,
  infoIcon,
  exclamationTriangleIcon,
  exclamationCircleIcon,
  type CanvasSystemIcon,
} from '@workday/canvas-system-icons-web';

import {useToastQueue, type ToastVariant} from '@/registry/canvasmith/hooks/use-toast';

/** Placement of the toast region within the viewport. */
export type ToastCenterPlacement =
  | 'top-start'
  | 'top-end'
  | 'bottom-start'
  | 'bottom-end';

export interface ToastCenterProps {
  /** Where the stack of toasts is anchored. @default 'bottom-end' */
  placement?: ToastCenterPlacement;
}

const variantConfig: Record<ToastVariant, {icon: CanvasSystemIcon; color: string}> = {
  success: {icon: checkIcon, color: system.color.fg.positive.default},
  info: {icon: infoIcon, color: system.color.fg.primary.default},
  caution: {icon: exclamationTriangleIcon, color: system.color.fg.caution.default},
  critical: {icon: exclamationCircleIcon, color: system.color.fg.critical.default},
};

const regionStyles = createStyles({
  position: 'fixed',
  zIndex: 1,
  display: 'flex',
  flexDirection: 'column',
  gap: system.space.x3,
  padding: system.space.x6,
  // Let clicks pass through the gaps between toasts to the page beneath.
  pointerEvents: 'none',
  maxBlockSize: '100vh',
  overflow: 'hidden',
  '& > *': {
    pointerEvents: 'auto',
  },
});

const placementStyles: Record<ToastCenterPlacement, string> = {
  'top-start': createStyles({
    insetBlockStart: 0,
    insetInlineStart: 0,
    alignItems: 'flex-start',
  }),
  'top-end': createStyles({
    insetBlockStart: 0,
    insetInlineEnd: 0,
    alignItems: 'flex-end',
  }),
  'bottom-start': createStyles({
    insetBlockEnd: 0,
    insetInlineStart: 0,
    alignItems: 'flex-start',
    flexDirection: 'column-reverse',
  }),
  'bottom-end': createStyles({
    insetBlockEnd: 0,
    insetInlineEnd: 0,
    alignItems: 'flex-end',
    flexDirection: 'column-reverse',
  }),
};

const toastDepthStyles = createStyles({
  boxShadow: system.depth[5],
});

/**
 * Renders the queued toasts from {@link useToast} in a fixed, viewport-anchored
 * region. Each toast is a Canvas `Toast`: `critical` toasts use `mode="alert"`
 * (assertive `aria-live`) so errors interrupt, while all others use `mode="status"`
 * (polite). The icon + label pairing keeps meaning from being color-only.
 *
 * Render this once, inside a `ToastProvider`, near the application root:
 *
 * ```tsx
 * <ToastProvider>
 *   <App />
 *   <ToastCenter placement="bottom-end" />
 * </ToastProvider>
 * ```
 */
export const ToastCenter = ({placement = 'bottom-end'}: ToastCenterProps) => {
  const {toasts, dismiss} = useToastQueue();

  return (
    <Box
      cs={[regionStyles, placementStyles[placement]]}
      // The region itself is a non-interactive container; individual toasts carry
      // their own aria-live semantics via `mode`.
      aria-hidden={toasts.length === 0 ? true : undefined}
    >
      {toasts.map(toast => {
        const {icon, color} = variantConfig[toast.variant];
        const mode = toast.variant === 'critical' ? 'alert' : 'status';

        return (
          <Toast key={toast.id} mode={mode} cs={toastDepthStyles}>
            <Toast.Icon icon={icon} color={color} />
            <Toast.Body>
              <Toast.Message>{toast.message}</Toast.Message>
            </Toast.Body>
            <Toast.CloseIcon
              aria-label="Dismiss notification"
              onClick={() => dismiss(toast.id)}
            />
          </Toast>
        );
      })}
    </Box>
  );
};

'use client';

import * as React from 'react';

/** Semantic tone of a toast, mapped to a Canvas status color + icon. */
export type ToastVariant = 'success' | 'info' | 'caution' | 'critical';

/** Options accepted by `showToast`. */
export interface ShowToastOptions {
  /** Visual + semantic tone. @default 'info' */
  variant?: ToastVariant;
  /** The message body. */
  message: React.ReactNode;
  /**
   * Auto-dismiss delay in milliseconds. Pass `0` to keep the toast until it is
   * dismissed manually. `'critical'` toasts default to persistent so errors are not
   * missed.
   * @default 6000 (0 for 'critical')
   */
  duration?: number;
}

/** A queued toast with its generated id and resolved variant. */
export interface ToastItem {
  id: string;
  variant: ToastVariant;
  message: React.ReactNode;
  duration: number;
}

/** The imperative API returned by {@link useToast}. */
export interface ToastApi {
  /** Enqueue a toast and return its id (useful for manual dismissal). */
  showToast: (options: ShowToastOptions) => string;
  /** Dismiss a specific toast by id. */
  dismiss: (id: string) => void;
  /** Dismiss every active toast. */
  dismissAll: () => void;
}

interface ToastContextValue extends ToastApi {
  toasts: ToastItem[];
}

const ToastContext = React.createContext<ToastContextValue | null>(null);

const DEFAULT_DURATION = 6000;

let counter = 0;
function nextId(): string {
  counter += 1;
  return `cnvs-toast-${counter}`;
}

export interface ToastProviderProps {
  children: React.ReactNode;
  /**
   * Maximum number of toasts shown at once. When exceeded, the oldest toast is
   * dropped. @default 4
   */
  max?: number;
}

/**
 * Provides the toast queue to the tree. Pair with `<ToastCenter />` (rendered once
 * near the root) to display the queued toasts, and call {@link useToast} anywhere
 * below this provider to enqueue them.
 *
 * ```tsx
 * <ToastProvider>
 *   <App />
 *   <ToastCenter />
 * </ToastProvider>
 * ```
 */
export const ToastProvider = ({children, max = 4}: ToastProviderProps) => {
  const [toasts, setToasts] = React.useState<ToastItem[]>([]);
  const timers = React.useRef(new Map<string, ReturnType<typeof setTimeout>>());

  const clearTimer = React.useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (timer) {
      clearTimeout(timer);
      timers.current.delete(id);
    }
  }, []);

  const dismiss = React.useCallback(
    (id: string) => {
      clearTimer(id);
      setToasts(prev => prev.filter(t => t.id !== id));
    },
    [clearTimer]
  );

  const dismissAll = React.useCallback(() => {
    timers.current.forEach(timer => clearTimeout(timer));
    timers.current.clear();
    setToasts([]);
  }, []);

  const showToast = React.useCallback(
    ({variant = 'info', message, duration}: ShowToastOptions) => {
      const id = nextId();
      const resolvedDuration =
        duration ?? (variant === 'critical' ? 0 : DEFAULT_DURATION);
      const item: ToastItem = {id, variant, message, duration: resolvedDuration};

      setToasts(prev => {
        const next = [...prev, item];
        // Drop the oldest toasts (and their timers) beyond the cap.
        while (next.length > max) {
          const removed = next.shift();
          if (removed) {
            clearTimer(removed.id);
          }
        }
        return next;
      });

      if (resolvedDuration > 0) {
        const timer = setTimeout(() => dismiss(id), resolvedDuration);
        timers.current.set(id, timer);
      }

      return id;
    },
    [clearTimer, dismiss, max]
  );

  // Clear all pending timers on unmount.
  React.useEffect(() => {
    const map = timers.current;
    return () => {
      map.forEach(timer => clearTimeout(timer));
      map.clear();
    };
  }, []);

  const value = React.useMemo<ToastContextValue>(
    () => ({toasts, showToast, dismiss, dismissAll}),
    [toasts, showToast, dismiss, dismissAll]
  );

  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>;
};

/**
 * Access the toast queue. Must be called within a {@link ToastProvider}.
 *
 * ```tsx
 * const {showToast} = useToast();
 * showToast({variant: 'success', message: 'Workbook saved.'});
 * ```
 */
export function useToast(): ToastApi {
  const context = React.useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a <ToastProvider>.');
  }
  const {showToast, dismiss, dismissAll} = context;
  return {showToast, dismiss, dismissAll};
}

/**
 * Internal accessor used by `<ToastCenter />` to read the live queue. Throws if used
 * outside a {@link ToastProvider}.
 */
export function useToastQueue(): ToastContextValue {
  const context = React.useContext(ToastContext);
  if (!context) {
    throw new Error('useToastQueue must be used within a <ToastProvider>.');
  }
  return context;
}
